import{_ as p,a0 as e,w as b,s as i,ao as o,I as s,x as u,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Ubuntu 所有版本的吉祥物 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 所有版本的吉祥物 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 所有版本的吉祥物 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 所有版本的吉祥物 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20220519 For the Love of Ubuntu- Here are the Mascots of All Ubuntu Releases","title":"Ubuntu 所有版本的吉祥物","tag":"202211","desc":""},"relativePath":"202211/20220519 For the Love of Ubuntu- Here are the Mascots of All Ubuntu Releases.md","filePath":"[post].md"}'),l={name:"202211/20220519 For the Love of Ubuntu- Here are the Mascots of All Ubuntu Releases.md"};function c(h,t,m,d,g,U){const a=e("Link");return b(),i("div",null,[t[18]||(t[18]=o('<h1 id="ubuntu-所有版本的吉祥物" tabindex="-1">Ubuntu 所有版本的吉祥物 <a class="header-anchor" href="#ubuntu-所有版本的吉祥物" aria-label="Permalink to “Ubuntu 所有版本的吉祥物”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/11/130502q6500yvm0znvktz9.jpg" alt=""></p><blockquote><p>在這篇文章中，我們會介紹迄今為止所有 Ubuntu 發行版本的吉祥物。</p></blockquote><p>你可能已經注意到了：每個 Ubuntu 版本都會有一個版本名稱和代號。代號由兩個單詞組成，這兩個單詞有相同的首字母，第一個單詞是形容詞，另一個單詞通常是一個瀕危的物種名稱。</p><p>對應於其代號，這些 Ubuntu 版本也有一個吉祥物。例如，Ubuntu 22.04 的代號為 “Jammy Jellyfish”，因此 Ubuntu 22.04 的桌面壁紙上有 <strong>吉祥物：水母</strong> 的圖像。</p><p>但是實際上，這些“吉祥物”並不總是 Ubuntu 版本的一部分，因為吉祥物在早期的 Ubuntu 版本中是沒有的。</p><p>有史以來第一個 Ubuntu 版本是在 2004 年 10 月發佈的 4.10 版（LCTT 譯註：Ubuntu 的版本號是由年份和月份的組合來表示的。）但是，直到 Ubuntu 8.04 LTS “Hardy Heron” 版本，你才會看到相關的吉祥物。</p>',7)),s("p",null,[t[1]||(t[1]=u("在我之前寫的 ",-1)),r(a,{href:"https://itsfoss.com/Ubuntu-default-wallpapers-download/"},{default:n(()=>[...t[0]||(t[0]=[u("另一篇文章",-1)])]),_:1}),t[2]||(t[2]=u(" 中，我整理了所有 Ubuntu 版本的默認壁紙。在本文中，你將瞭解到所有 Ubuntu 版本的吉祥物。",-1))]),t[19]||(t[19]=o('<p>現在，就讓我們按時間倒序，一起進入 Ubuntu 的吉祥物之旅吧。</p><p>（LCTT 校注：本文原文發表時，Ubuntu 22.10 尚未發佈，它的代號是 “Kinetic Kudu”，吉祥物是“捻角羚”。）</p><p>（LCTT 校注：由於 Ubuntu 系列的代號和吉祥物選擇的都是比較少見的動物和晦澀的描述，因此儘管譯者和校對雖然盡力了，但是應該還有謬誤。我覺得原文作者為了找出這些説明也盡力，恐怕真正權威的詮釋只有 Canonical 才能給出吧。）</p><h3 id="ubuntu-22-04-jammy-jellyfish-幸運水母" tabindex="-1">Ubuntu 22.04 Jammy Jellyfish（幸運水母） <a class="header-anchor" href="#ubuntu-22-04-jammy-jellyfish-幸運水母" aria-label="Permalink to “Ubuntu 22.04 Jammy Jellyfish（幸運水母）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-22-04-mascot.jpg" alt="Ubuntu 22.04 mascot"></p><p>於 2021 年 4 月 21 日發佈。</p><p>Jammy 的意思是被果醬覆蓋着的、充滿果醬的。不太正式地，Jammy 還有<strong>幸運</strong>的意思。</p><p><ruby>水母<rt> Jellyfish </rt></ruby> 是一種自由遊動的水生動物，它的身體就像是一把透明傘，還具有拖曳的觸鬚。少數水母是通過莖幹固定在海牀上，而不能移動。全世界的海洋中有超過兩百種的水母，它們分佈於全球各地的水域裏。</p><h3 id="ubuntu-21-10-impish-indri-頑皮大狐猴" tabindex="-1">Ubuntu 21.10 Impish Indri（頑皮大狐猴） <a class="header-anchor" href="#ubuntu-21-10-impish-indri-頑皮大狐猴" aria-label="Permalink to “Ubuntu 21.10 Impish Indri（頑皮大狐猴）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-21-10-mascot.jpg" alt="Ubuntu 21.10 mascot"></p><p>於 2021 年 10 月 14 日發佈。</p><p>Impish 的意思是以<strong>頑皮</strong>而不是嚴肅的方式，對某人/某事不太尊重。</p><p><ruby>大狐猴<rt> Indri </rt></ruby>，也稱為 babakoto，是現存的最大的狐猴之一。它的頭身長約 64 至 72 釐米，體重在 6 至 9.5 公斤之間。它的毛髮是黑白相間的。在攀爬或攀爬時，它會保持豎直的姿勢。</p><blockquote><p>據維基：2014 年的世界自然保護聯盟（IUCN） <ruby>紅色名錄<rt> Red List </rt></ruby> 中，僅出現在馬達加斯加的大狐猴首次被提升至極危級別。</p></blockquote><h3 id="ubuntu-21-04-hirsute-hippo-多毛河馬" tabindex="-1">Ubuntu 21.04 Hirsute Hippo（多毛河馬） <a class="header-anchor" href="#ubuntu-21-04-hirsute-hippo-多毛河馬" aria-label="Permalink to “Ubuntu 21.04 Hirsute Hippo（多毛河馬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-21-04-mascot.jpg" alt="Ubuntu 21.04 mascot"></p><p>於 2021 年 4 月 22 日發佈。</p><p>Hirsute 的意思是<strong>多毛的</strong>。</p><p><ruby>河馬<rt> Hippo </rt></ruby>，是一種生活在非洲大陸撒哈拉以南的大型半水生哺乳動物。河馬是河馬科中僅有的兩個現存物種之一，另一個物種是 <ruby>侏儒河馬<rt> pygmy hippopotamus </rt></ruby>。河馬的名字來源於古希臘語“river horse”。</p><blockquote><p>據維基：在 2006 年 5 月已被 IUCN 紅色名錄中分為易危物種，世界僅存約 12.5 萬－15 萬頭</p></blockquote><p>但是其實，我並沒有見過很多多毛的河馬 😅。</p><h3 id="ubuntu-20-10-groovy-gorilla-時髦大猩猩" tabindex="-1">Ubuntu 20.10 Groovy Gorilla（時髦大猩猩） <a class="header-anchor" href="#ubuntu-20-10-groovy-gorilla-時髦大猩猩" aria-label="Permalink to “Ubuntu 20.10 Groovy Gorilla（時髦大猩猩）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-20-10-mascot.jpg" alt="Ubuntu 20.10 mascot"></p><p>於 2020 年 10 月 22 日發佈。</p><p>Groovy 的意思是<strong>時尚的</strong>和令人興奮的。</p><p><ruby>大猩猩<rt> Gorilla </rt></ruby>，是一種草​​食性的地棲巨猿。它主要棲息在赤道非洲的熱帶森林中。大猩猩屬分為兩個物種：東部大猩猩和西部大猩猩，以及進一步可分為四個或五個亞種。</p><h3 id="ubuntu-20-04-lts-focal-fossa-矚目狸貓" tabindex="-1">Ubuntu 20.04 LTS Focal Fossa（矚目狸貓） <a class="header-anchor" href="#ubuntu-20-04-lts-focal-fossa-矚目狸貓" aria-label="Permalink to “Ubuntu 20.04 LTS Focal Fossa（矚目狸貓）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-20-04-mascot-1.jpg" alt="Ubuntu 20.04 mascot"></p><p>於 2020 年 4 月 23 日發佈。</p><p>Focal 的意思是令人注目的、<strong>矚目</strong>。</p><p><ruby>馬島長尾狸貓<rt> Fossa </rt></ruby>，是<strong>馬達加斯加島上最大的食肉性哺乳動物</strong>。它身體的長度可以達到近六英尺，其中它們的長尾巴佔了一半。它們看起來就像是貓、狗和獴的雜交體。它們有細長的身體、肌肉發達的四肢和短的紅棕色毛髮。</p><h3 id="ubuntu-19-10-eoan-ermine-東方白鼬" tabindex="-1">Ubuntu 19.10 Eoan Ermine（東方白鼬） <a class="header-anchor" href="#ubuntu-19-10-eoan-ermine-東方白鼬" aria-label="Permalink to “Ubuntu 19.10 Eoan Ermine（東方白鼬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-19-10-mascot.jpg" alt="Ubuntu 19.10 mascot"></p><p>於 2019 年 10 月 17 日發佈。</p><p>Eoan 的意思是<strong>與黎明或東方有關的</strong>。</p><p><ruby>白鼬<rt> Stoat </rt></ruby>，也被稱為歐亞貂、白令貂，簡稱 <ruby>貂<rt> Ermine </rt></ruby>，是一種原產於歐亞大陸和北美北部的鼬科動物。由於鼬在極地廣泛分佈，因此它被 IUCN 列為最不擔憂滅絕的物種。</p><blockquote><p>據維基：IUCN 將其列為世界百大外來入侵種。</p></blockquote><h3 id="ubuntu-19-04-disco-dingo-迪斯科野犬" tabindex="-1">Ubuntu 19.04 Disco Dingo（迪斯科野犬） <a class="header-anchor" href="#ubuntu-19-04-disco-dingo-迪斯科野犬" aria-label="Permalink to “Ubuntu 19.04 Disco Dingo（迪斯科野犬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-19-04-mascot.jpg" alt="Ubuntu 19.04 mascot"></p><p>於 2019 年 4 月 18 日發佈。</p><p>Disco 與<strong>迪斯科</strong>音樂和夜總會有關。</p><p><ruby>澳洲野犬<rt> Dingo </rt></ruby>，是在澳大利亞發現的一種古老的犬種。澳洲野犬的科屬分類在不同出版物中不太一樣，因此它的科屬分類存在爭議。</p><h3 id="ubuntu-18-10-cosmic-cuttlefish-外星墨魚" tabindex="-1">Ubuntu 18.10 Cosmic Cuttlefish（外星墨魚） <a class="header-anchor" href="#ubuntu-18-10-cosmic-cuttlefish-外星墨魚" aria-label="Permalink to “Ubuntu 18.10 Cosmic Cuttlefish（外星墨魚）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-18-10-mascot.jpg" alt="Ubuntu 18.10 mascot"></p><p>於 2018 年 10 月 18 日發佈。</p><p>Cosmic 意味着與地球<strong>不同的</strong>、宇宙的。</p><p><ruby>墨魚<rt> Cuttlefish </rt></ruby>，是烏賊目的一種海洋軟體動物。它屬於頭足類，這一類還包含了魷魚、章魚和鸚鵡螺。墨魚有一個獨特的內殼，即墨魚骨，它可以用於控制浮力。</p><h3 id="ubuntu-18-04-lts-bionic-beaver-仿生河狸" tabindex="-1">Ubuntu 18.04 LTS Bionic Beaver（仿生河狸） <a class="header-anchor" href="#ubuntu-18-04-lts-bionic-beaver-仿生河狸" aria-label="Permalink to “Ubuntu 18.04 LTS Bionic Beaver（仿生河狸）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-18-04-mascot.jpg" alt="Ubuntu 18.04 mascot"></p><p>於 2018 年 4 月 26 日發佈。</p><p>Bionic 意味着<strong>仿生的</strong>，或者是機電的。</p><p><ruby>河狸<rt> Beaver </rt></ruby>，是北半球温帶的一種大型半水生齧齒動物。有兩種現存的海狸：北美河狸和歐亞河狸。河狸是僅次於水豚的現存第二大齧齒動物。</p><blockquote><p>據維基：它們處於 IUCN 哺乳動物紅色名錄中的無危物種，在中國河狸被列為一級保護動物。</p></blockquote><p>英國用户認為這個版本的名稱特別有趣。</p><h3 id="ubuntu-17-10-artful-aardvark-機靈土豚" tabindex="-1">Ubuntu 17.10 Artful Aardvark（機靈土豚） <a class="header-anchor" href="#ubuntu-17-10-artful-aardvark-機靈土豚" aria-label="Permalink to “Ubuntu 17.10 Artful Aardvark（機靈土豚）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-17-10-mascot.jpg" alt="Ubuntu 17.10 mascot"></p><p>於 2017 年 10 月 19 日發佈。</p><p>Ubuntu 在此版本中默認切換回了 GNOME。</p><p>Artful 的意思是聰明的或<strong>機靈的</strong>。</p><p><ruby>土豚<rt> Aardvark </rt></ruby>，是一種原產於非洲的穴居、夜間活動的中型哺乳動物。它是管齒目中唯一的現存物種。與大多數其他食蟲動物不同，它有一個長長的像豬一樣的鼻子，可以聞出食物在哪裏。</p><h3 id="ubuntu-17-04-zesty-zapus-開心跳鼠" tabindex="-1">Ubuntu 17.04 Zesty Zapus（開心跳鼠） <a class="header-anchor" href="#ubuntu-17-04-zesty-zapus-開心跳鼠" aria-label="Permalink to “Ubuntu 17.04 Zesty Zapus（開心跳鼠）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-17-04-mascot.jpg" alt="Ubuntu 17.04 mascot"></p><p>於 2017 年 4 月 13 日發佈。</p><p>這個版本是最後一個以 Unity 桌面為特色的版本。</p><p>Zesty 意味着有一種強烈的、<strong>令人開心的</strong>、有點辛辣的味道。</p><p><ruby>跳鼠<rt>Zapus</rt></ruby> 是北美跳鼠中唯一一個有牙齒的一個屬。跳鼠是除 <ruby>指猴<rt> Aye-aye </rt></ruby>之外，唯一現存的有 18 顆牙齒的哺乳動物。</p><h3 id="ubuntu-16-10-yakkety-yak-嘮叨犛牛" tabindex="-1">Ubuntu 16.10 Yakkety Yak（嘮叨犛牛） <a class="header-anchor" href="#ubuntu-16-10-yakkety-yak-嘮叨犛牛" aria-label="Permalink to “Ubuntu 16.10 Yakkety Yak（嘮叨犛牛）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-16-10-mascot.jpg" alt="Ubuntu 16.10 mascot"></p><p>於 2016 年 10 月 13 日發佈。</p><p>Yakkety 有很多意思。OMG Ubuntu 説，“yakking” 有嘮嘮叨叨這一非正式意思，yakkety 還可能是一種知名的流行爵士樂器 “Yakety Sax” 的另一種拼寫。</p><p><ruby>犛牛<rt> Yak </rt></ruby>，是一種大型馴養的野牛。它的毛髮蓬鬆，肩部隆起，有很大的角。在一些地方它是一種馱畜，人們也可以食用它的奶和肉、以及加工它的皮製作東西。</p><h3 id="ubuntu-16-04-lts-xenial-xerus-好客地松鼠" tabindex="-1">Ubuntu 16.04 LTS Xenial Xerus（好客地松鼠） <a class="header-anchor" href="#ubuntu-16-04-lts-xenial-xerus-好客地松鼠" aria-label="Permalink to “Ubuntu 16.04 LTS Xenial Xerus（好客地松鼠）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-16-04-mascot.jpg" alt="Ubuntu 16.04 mascot"></p><p>於 2016 年 4 月 21 日發佈。</p><p>Xenial 的意思是<strong>熱情好客的</strong>。</p><p><ruby>非洲地松鼠<rt> Xerus </rt></ruby>，有四個亞種，分別是<strong>開普地松鼠，條紋地松鼠，山地松鼠和無條紋地松鼠</strong>。這些動物是晝行性的，是食草動物，通常吃堅果、根和種子。然而，有時它們也會吃蛋類和其他小動物。</p><h3 id="ubuntu-15-10-wily-werewolf-狡猾狼人" tabindex="-1">Ubuntu 15.10 Wily Werewolf（狡猾狼人） <a class="header-anchor" href="#ubuntu-15-10-wily-werewolf-狡猾狼人" aria-label="Permalink to “Ubuntu 15.10 Wily Werewolf（狡猾狼人）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-15-10-mascot.jpg" alt="Ubuntu 15.10 mascot"></p><p>於 2015 年 10 月 22 日發佈。</p><p>這個版本可能是少有的發佈代號中帶有虛構動物的 Ubuntu 版本之一。</p><p>Wily 的意思是善於獲得優勢，尤其在欺騙上十分<strong>狡猾的</strong>。</p><p><ruby>狼人<rt> Werewolf </rt></ruby>，是可以隱藏住耳朵和尾巴的一種神話生物。它是人，也是狼，大多數人因為它們的長相而害怕它們。</p><h3 id="ubuntu-15-04-vivid-vervet-活潑綠猴" tabindex="-1">Ubuntu 15.04 Vivid Vervet（活潑綠猴） <a class="header-anchor" href="#ubuntu-15-04-vivid-vervet-活潑綠猴" aria-label="Permalink to “Ubuntu 15.04 Vivid Vervet（活潑綠猴）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-15-04-mascot.jpg" alt="Ubuntu 15.04 mascot"></p><p>於 2015 年 4 月 23 日發佈。</p><p>Vivid 的意思是<strong>活潑</strong>的、明亮的。</p><p><ruby>黑長尾猴<rt> Vervet monkey </rt></ruby>，是一種原產於非洲的角猿科的舊大陸猴。“vervet”一詞也用於表示<ruby>綠猴屬<rt> Chlorocebus </rt></ruby>的所有動物，其中包含五個不同的亞種，這五個不同的亞種主要分佈在南部非洲以及一些東部國家。</p><h3 id="ubuntu-14-10-utopic-unicorn-烏托邦獨角獸" tabindex="-1">Ubuntu 14.10 Utopic Unicorn（烏托邦獨角獸） <a class="header-anchor" href="#ubuntu-14-10-utopic-unicorn-烏托邦獨角獸" aria-label="Permalink to “Ubuntu 14.10 Utopic Unicorn（烏托邦獨角獸）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-14-10-mascot.jpg" alt="Ubuntu 14.10 mascot"></p><p>於 2014 年 10 月 23 日發佈。</p><p>這個版本是另一個其發佈代號中帶有虛構動物的 Ubuntu 版本。</p><p>Utopic 與<strong>烏托邦</strong>有關，烏托邦是一個虛構的、不存在但是一個理想的地方。</p><p><ruby>獨角獸<rt> Unicorn </rt></ruby>，是一種傳説中的生物。自古以來，它就被描述為前額有一個巨大的、尖的、螺旋狀的角的一種野獸。</p><h3 id="ubuntu-14-04-lts-trusty-tahr-可靠塔爾羊" tabindex="-1">Ubuntu 14.04 LTS Trusty Tahr（可靠塔爾羊） <a class="header-anchor" href="#ubuntu-14-04-lts-trusty-tahr-可靠塔爾羊" aria-label="Permalink to “Ubuntu 14.04 LTS Trusty Tahr（可靠塔爾羊）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-14-04-mascot.jpg" alt="Ubuntu 14.04 mascot"></p><p>於 2014 年 4 月 17 日發佈。</p><p>Trusty 意味着<strong>可靠的</strong>或忠實的。</p><p><ruby>塔爾羊<rt> Tahr </rt></ruby>，是一種很像山羊的哺乳動物。它們會棲息在阿曼、印度南部和喜馬拉雅山脈的懸崖和山坡上。</p><h3 id="ubuntu-13-10-saucy-salamander-活潑蠑螈" tabindex="-1">Ubuntu 13.10 Saucy Salamander（活潑蠑螈） <a class="header-anchor" href="#ubuntu-13-10-saucy-salamander-活潑蠑螈" aria-label="Permalink to “Ubuntu 13.10 Saucy Salamander（活潑蠑螈）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-13-10-mascot.jpg" alt="Ubuntu 13.10 mascot"></p><p>於 2013 年 10 月 17 日發佈。</p><p>Saucy 意味着大膽的、<strong>活潑的</strong>或精神飽滿的。</p><p><ruby>蠑螈<rt> Salamander </rt></ruby>是一類兩棲動物。其典型特徵是有着蜥蜴般的外觀，它們有細長的身體，鈍的鼻子，以及與身體成直角突出的短肢，並且幼體和成體都有尾巴。現存的所有十個蠑螈科都屬於有尾目。</p><h3 id="ubuntu-13-04-raring-ringtail-熱情貓熊" tabindex="-1">Ubuntu 13.04 Raring Ringtail（熱情貓熊） <a class="header-anchor" href="#ubuntu-13-04-raring-ringtail-熱情貓熊" aria-label="Permalink to “Ubuntu 13.04 Raring Ringtail（熱情貓熊）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-13-04-mascot.jpg" alt="Ubuntu 13.04 mascot"></p><p>於 2013 年 4 月 25 日發佈。</p><p>Raring 的意思是熱情的和<strong>非常渴望做某事</strong>。</p><p><ruby>貓熊<rt> Ringtail </rt></ruby>，是<strong>一種像貓一樣大的食肉動物，類似於一隻長着浣熊尾巴的小狐狸</strong>。它濃密的尾巴是扁平的，幾乎和頭部和身體一樣長，有黑白交替的環。它們是夜行動物，一天中的大部分時間都在它們的巢穴裏睡覺。</p><h3 id="ubuntu-12-10-quantal-quetzal-量子大咬鵑" tabindex="-1">Ubuntu 12.10 Quantal Quetzal（量子大咬鵑） <a class="header-anchor" href="#ubuntu-12-10-quantal-quetzal-量子大咬鵑" aria-label="Permalink to “Ubuntu 12.10 Quantal Quetzal（量子大咬鵑）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-12-10-mascot.jpg" alt="Ubuntu 12.10 mascot"></p><p>於 2012 年 10 月 18 日發佈。</p><p>Quantal 意味着與<strong>量子</strong>或量子理論有關的。</p><p><ruby>大咬鵑<rt> Quetzal </rt></ruby>，是咬鵑家族中的一種色彩鮮豔的鳥類。它們生活在森林中，主要是在潮濕的高地。來自<em>鳳尾綠咬鵑屬</em>的五種物種生活在新熱帶的，而另外一個物種，即角咬鵑，生活在墨西哥和美國最南端的局部地區。大咬鵑相當地大，它們的身體長度超過 32 釐米或者有 13 英寸長，比其他咬鵑科的物種都大。絢麗的大咬鵑因其鮮豔的色彩，而成為危地馬拉的國鳥。</p><h3 id="ubuntu-12-04-lts-precise-pangolin-精準穿山甲" tabindex="-1">Ubuntu 12.04 LTS Precise Pangolin（精準穿山甲） <a class="header-anchor" href="#ubuntu-12-04-lts-precise-pangolin-精準穿山甲" aria-label="Permalink to “Ubuntu 12.04 LTS Precise Pangolin（精準穿山甲）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-12-04-mascot.jpg" alt="Ubuntu 12.04 mascot"></p><p>於 2012 年 4 月 26 日發佈。</p><p>Precise 意味着能<strong>精確</strong>或準確地表達細節。</p><p><ruby>穿山甲<rt> Pangolin </rt></ruby>，有時被稱為有鱗食蟻獸，是鱗甲目的一種哺乳動物。它現存的一個科是穿山甲科，有三個屬：穿山甲亞屬、長尾穿山甲亞屬和地穿山甲亞屬。穿山甲亞屬包括在亞洲發現的四種物種，而長尾穿山甲亞屬和地穿山甲亞屬各包括兩種物種，均在撒哈拉以南非洲發現。</p><blockquote><p>據維基百科：2014 年，IUCN 紅色名錄物種存續委員會穿山甲專門小組，指出穿山甲是目前全世界最常被走私買賣的哺乳動物。所有穿山甲都面臨巨大的生存威脅，其中中華穿山甲和馬來穿山甲被 IUCN 評估為“極危”物種，非法走私的活動極為猖獗。隨着亞洲的 4 種穿山甲數量鋭減，走私貿易商家已轉移目標至非洲，以滿足市場上的龐大需求。</p></blockquote><h3 id="ubuntu-11-10-oneiric-ocelot-夢幻豹貓" tabindex="-1">Ubuntu 11.10 Oneiric Ocelot（夢幻豹貓） <a class="header-anchor" href="#ubuntu-11-10-oneiric-ocelot-夢幻豹貓" aria-label="Permalink to “Ubuntu 11.10 Oneiric Ocelot（夢幻豹貓）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-11-10-mascot.jpg" alt="Ubuntu 11.10 mascot"></p><p>於 2011 年 10 月 13 日發佈。</p><p>Oneiric 的意思是與<strong>夢</strong>有關的。</p><p><ruby>豹貓<rt> Ocelot </rt></ruby>，是一種中等大小的斑點野貓。它的肩長可達 40 至 50 釐米，體重在 8 至 15.5 公斤之間。<ruby>卡爾·林奈<rt>Carl Linnaeus</rt></ruby> 於 1758 年首次在書中描述了它。</p><blockquote><p>據維基：華盛頓公約將孟加拉國、印度以及泰國的豹貓族羣列入附錄一禁止進行國際貿易，而其他族羣亦列入華盛頓公約附錄二。</p></blockquote><h3 id="ubuntu-11-04-natty-narwhal-聰明獨角鯨" tabindex="-1">Ubuntu 11.04 Natty Narwhal（聰明獨角鯨） <a class="header-anchor" href="#ubuntu-11-04-natty-narwhal-聰明獨角鯨" aria-label="Permalink to “Ubuntu 11.04 Natty Narwhal（聰明獨角鯨）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-11-04-mascot.jpg" alt="Ubuntu 11.04 mascot"></p><p>於 2011 年 4 月 28 日發佈。</p><p>這個版本是第一個採用 Unity 桌面的版本。</p><p>Natty 意味着<strong>聰明</strong>和時尚的。</p><p><ruby>獨角鯨<rt> Narwhal </rt></ruby>，是一種中等大小的齒鯨。擁有一顆突出的犬齒的大“獠牙”。它常年生活在格陵蘭、加拿大和俄羅斯周圍的北極水域。它是一角鯨科中現存的兩種鯨魚物種之一，另一個物種是 <ruby>白鯨<rt> Beluga whale </rt></ruby>。</p><h3 id="ubuntu-10-10-maverick-meerkat-獨行貓鼬" tabindex="-1">Ubuntu 10.10 Maverick Meerkat（獨行貓鼬） <a class="header-anchor" href="#ubuntu-10-10-maverick-meerkat-獨行貓鼬" aria-label="Permalink to “Ubuntu 10.10 Maverick Meerkat（獨行貓鼬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-10-10-mascot.jpg" alt="Ubuntu 10.10 mascot"></p><p>於 2010 年 10 月 10 日發佈。</p><p>Maverick 的意思是<strong>特立獨行的</strong>或有獨立思想的。</p><p><ruby>貓鼬<rt> Meerkat </rt></ruby>，是一種在南部非洲發現的小型貓鼬。它的特點是頭寬、眼睛大、鼻子尖、腿長、尾巴很細，毛色有斑紋。</p><h3 id="ubuntu-10-04-lts-lucid-lynx-清醒猞狸" tabindex="-1">Ubuntu 10.04 LTS Lucid Lynx（清醒猞狸） <a class="header-anchor" href="#ubuntu-10-04-lts-lucid-lynx-清醒猞狸" aria-label="Permalink to “Ubuntu 10.04 LTS Lucid Lynx（清醒猞狸）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-10-04-mascot.jpg" alt="Ubuntu 10.04 mascot"></p><p>於 2010 年 4 月 29 日發佈。</p><p>Lucid 意味着<strong>易於理解的</strong>或明亮的。</p><p><ruby>猞猁<rt> Lynx </rt></ruby>，是中型野貓屬猞猁中的一種。猞猁這個名字起源於中古英語，源自希臘語 λύγξ，λύγξ 又源自於印歐語詞根 leuk-，指的是它眼睛能反射發光的樣子。</p><h3 id="ubuntu-9-10-karmic-koala-幸運考拉" tabindex="-1">Ubuntu 9.10 Karmic Koala（幸運考拉） <a class="header-anchor" href="#ubuntu-9-10-karmic-koala-幸運考拉" aria-label="Permalink to “Ubuntu 9.10 Karmic Koala（幸運考拉）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-9-10-mascot.jpg" alt="Ubuntu 9.10 mascot"></p><p>於 2009 年 10 月 29 日發佈。</p><p>Karmic 意味着與<strong>命運</strong>、業力有關。</p><p><ruby>考拉<rt> Koala </rt></ruby>，是一種原產於澳大利亞的樹棲草食性的有袋動物。它是袋鼠科唯一現存的物種，它的近親是<ruby>袋熊<rt> Wombat </rt></ruby>。</p><blockquote><p>據維基：在 19 世紀初樹袋熊遭到捕殺出口，數量由百萬只鋭減至一千多隻，於是澳大利亞政府立法保護。</p></blockquote><h3 id="ubuntu-9-04-jaunty-jackalope-自信鹿角兔" tabindex="-1">Ubuntu 9.04 Jaunty Jackalope（自信鹿角兔） <a class="header-anchor" href="#ubuntu-9-04-jaunty-jackalope-自信鹿角兔" aria-label="Permalink to “Ubuntu 9.04 Jaunty Jackalope（自信鹿角兔）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-9-04-mascot.jpg" alt="Ubuntu 9.04 mascot"></p><p>於 2009 年 4 月 23 日發佈。</p><p>這個版本是我用的第一個 Ubuntu 版本。</p><p>Jaunty 是指擁有活潑、開朗和<strong>自信</strong>的態度。</p><p><ruby>鹿角兔<rt> Jackalope </rt></ruby>，是<strong>北美民間傳説中的一種神話動物</strong>，被描述為長着羚羊角的可怕的長角兔。Jackalope 這個詞是由 jackrabbit 和 antelope 組合而成的。許多鹿角兔的標本都是由用鹿角製成的。</p><h3 id="ubuntu-8-10-intrepid-ibex-無畏野山羊" tabindex="-1">Ubuntu 8.10 Intrepid Ibex（無畏野山羊） <a class="header-anchor" href="#ubuntu-8-10-intrepid-ibex-無畏野山羊" aria-label="Permalink to “Ubuntu 8.10 Intrepid Ibex（無畏野山羊）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-8-10-mascot.jpg" alt="Ubuntu 8.10 mascot"></p><p>於 2008 年 10 月 30 日發佈。</p><p>Intrepid 意味着<strong>無所畏懼</strong>、冒險的。</p><p><ruby>野山羊<rt> Ibex </rt></ruby>，以雄性的大彎角為特徵，在前面形成像橫向的脊那樣。它主要分佈於歐亞大陸、北非和東非。</p><h3 id="ubuntu-8-04-lts-hardy-heron-堅韌蒼鷺" tabindex="-1">Ubuntu 8.04 LTS Hardy Heron（堅韌蒼鷺） <a class="header-anchor" href="#ubuntu-8-04-lts-hardy-heron-堅韌蒼鷺" aria-label="Permalink to “Ubuntu 8.04 LTS Hardy Heron（堅韌蒼鷺）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-8-04-mascot.jpg" alt="Ubuntu 8.04 mascot"></p><p>於 2008 年 4 月 24 日發佈。</p><p>這個版本是第一個吉祥物出現在其默認壁紙上的 Ubuntu 版本。</p><p>Hardy 意味着能夠<strong>忍受</strong>困難條件的、強大的。</p><p><ruby>蒼鷺<rt> Heron </rt></ruby>，是一種長腿、長頸、生活在淡水和沿海的鳥類。</p><h3 id="ubuntu-7-10-gutsy-gibbon-陣風長臂猿" tabindex="-1">Ubuntu 7.10 Gutsy Gibbon（陣風長臂猿） <a class="header-anchor" href="#ubuntu-7-10-gutsy-gibbon-陣風長臂猿" aria-label="Permalink to “Ubuntu 7.10 Gutsy Gibbon（陣風長臂猿）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-7-10-mascot.jpg" alt="Ubuntu 7.10 mascot"></p><p>於 2007 年 10 月 18 日發佈。</p><p>Gusty 表示以<strong>陣風</strong>的方式吹動。</p><p><ruby>長臂猿<rt> Gibbon </rt></ruby>，是一種猿類，它們生活在孟加拉國東部、印度東北部、中國南部和印度尼西亞的亞熱帶和熱帶雨林地區。</p><h3 id="ubuntu-7-04-feisty-fawn-活潑小鹿" tabindex="-1">Ubuntu 7.04 Feisty Fawn（活潑小鹿） <a class="header-anchor" href="#ubuntu-7-04-feisty-fawn-活潑小鹿" aria-label="Permalink to “Ubuntu 7.04 Feisty Fawn（活潑小鹿）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-7-04-mascot.jpg" alt="Ubuntu 7.04 mascot"></p><p>於 2007 年 4 月 19 日發佈。</p><p>Feisty 意味着<strong>小而堅定</strong>的。</p><p><ruby>小鹿<rt> Fawn </rt></ruby>，指的是第一年剛出生的小鹿。</p><h3 id="ubuntu-6-10-edgy-eft-緊張水蜥" tabindex="-1">Ubuntu 6.10 Edgy Eft（緊張水蜥） <a class="header-anchor" href="#ubuntu-6-10-edgy-eft-緊張水蜥" aria-label="Permalink to “Ubuntu 6.10 Edgy Eft（緊張水蜥）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-6-10-mascot.jpg" alt="Ubuntu 6.10 mascot"></p><p>於 2006 年 10 月 26 日發佈。</p><p>Edgy 的意思是<strong>緊張的</strong>。</p><p><ruby>水蜥<rt> Eft </rt></ruby>，是蠑螈的陸生幼年期。蠑螈是一種蜥蜴，它具有三個不同的發育生命階段：水生幼蟲、陸生幼體和成體。</p><p>所以水蜥指的是一個青年的蠑螈。</p><h3 id="ubuntu-6-06-dapper-drake-整潔公鴨" tabindex="-1">Ubuntu 6.06 Dapper Drake（整潔公鴨） <a class="header-anchor" href="#ubuntu-6-06-dapper-drake-整潔公鴨" aria-label="Permalink to “Ubuntu 6.06 Dapper Drake（整潔公鴨）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-6-06-mascot.jpg" alt="Ubuntu 6.06 mascot"></p><p>於 2006 年 6 月 1 日發佈。</p><p>Dapper 的意思是衣着整潔，<strong>外表整潔的</strong>。</p><p><ruby>公鴨<rt> Drake </rt></ruby>，是完全性成熟的成年雄性鴨子。</p><h3 id="ubuntu-5-10-breezy-badger-微風之獾" tabindex="-1">Ubuntu 5.10 Breezy Badger（微風之獾） <a class="header-anchor" href="#ubuntu-5-10-breezy-badger-微風之獾" aria-label="Permalink to “Ubuntu 5.10 Breezy Badger（微風之獾）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-5-10-mascot.jpg" alt="Ubuntu 5.10 mascot"></p><p>於 2005 年 10 月 12 日發佈。</p><p>Breezy 的意思是有<strong>微風</strong>的。</p><p><ruby>獾<rt> Badger </rt></ruby>，一種是短腿的雜食動物，經常蹲下身擠在一起。</p><h3 id="ubuntu-5-04-hoary-hedgehog-灰白刺蝟" tabindex="-1">Ubuntu 5.04 Hoary Hedgehog（灰白刺蝟） <a class="header-anchor" href="#ubuntu-5-04-hoary-hedgehog-灰白刺蝟" aria-label="Permalink to “Ubuntu 5.04 Hoary Hedgehog（灰白刺蝟）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-5-04-mascot.jpg" alt="Ubuntu 5.04 mascot"></p><p>於 2005 年 4 月 8 日發佈。</p><p>Hoary 是<strong>灰白色的</strong>意思。</p><p><ruby>刺蝟<rt> Hedgehogis </rt></ruby>，是一種多刺的哺乳動物，遍佈於歐洲、亞洲和非洲的部分地區，並引入到了新西蘭。</p><h3 id="ubuntu-4-10-warty-warthog-有疣疣豬" tabindex="-1">Ubuntu 4.10 : Warty Warthog（有疣疣豬） <a class="header-anchor" href="#ubuntu-4-10-warty-warthog-有疣疣豬" aria-label="Permalink to “Ubuntu 4.10 : Warty Warthog（有疣疣豬）”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/Ubuntu-4-10-mascot.jpg" alt="Ubuntu 4.10 mascot"></p><p>於 2004 年 10 月 20 日發佈。</p><p>Ubuntu 就是從這個版本開始的。</p><p>Wart 是由病毒引起的一種小的、堅硬的、良性的皮膚生長物。Warty 的意思是<strong>長滿疣的</strong>。</p><p><ruby>疣豬<rt> Warthog </rt></ruby>，是豬科的一種野生動物，它是在撒哈拉以南非洲的草原、稀樹草原和林地中被發現的。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文有沒有讓 Ubuntu 用户瞭解了更多知識呢？從技術上講，並沒有，但回顧歷史是件好事。如果你多年來一直是 Ubuntu 用户，那麼這篇文章可能會引發你的懷舊之情。</p><p>Ubuntu 9.04 是我第一次嘗試 Linux 桌面。如果我沒記錯的話，那是在 2009 年 9 月下旬。僅僅幾周後，我的系統就升級到了 Ubuntu 9.10。那些天我經常在 Ubuntu 論壇上瀏覽，探索這個新的操作系統，並學習新的東西。</p><p>那麼，這篇文章有沒有勾起你的一些美好的回憶呢？你的第一個 Ubuntu 版本又是哪個呢？在評論區中分享你的 Ubuntu 使用經歷吧。</p><hr>',206)),s("p",null,[t[4]||(t[4]=u("via: ",-1)),r(a,{href:"https://itsfoss.com/all-Ubuntu-mascots/"},{default:n(()=>[...t[3]||(t[3]=[u("https://itsfoss.com/all-Ubuntu-mascots/",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=u("作者：",-1)),r(a,{href:"https://itsfoss.com/author/abhishek/"},{default:n(()=>[...t[5]||(t[5]=[u("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=u(" 選題：",-1)),r(a,{href:"https://github.com/lkxed"},{default:n(()=>[...t[6]||(t[6]=[u("lkxed",-1)])]),_:1}),t[11]||(t[11]=u(" 譯者：",-1)),r(a,{href:"https://github.com/chai001125"},{default:n(()=>[...t[7]||(t[7]=[u("chai001125",-1)])]),_:1}),t[12]||(t[12]=u(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[u("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=u("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[u("LCTT",-1)])]),_:1}),t[16]||(t[16]=u(" 原創編譯，",-1)),r(a,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[u("Linux中國",-1)])]),_:1}),t[17]||(t[17]=u(" 榮譽推出",-1))])])}const x=p(l,[["render",c]]);export{k as __pageData,x as default};
